arguments.command:
python3 - <<'EOF'
import json, glob

total = 0
count = 0
for f in sorted(glob.glob('data/*.jsonl')):
    for line in open(f):
        line = line.strip()
        if not line:
            continue
        rec = json.loads(line)
        if rec.get('kind') != 'span':
            continue
        el = rec.get('body', {}).get('span', {}).get('elapsed')
        ms = 0
        if el is not None:
            v = el['value']; u = el['unit']
            if u == 'ms':
                ms = v
            elif u == 'us':
                ms = v // 1000
            elif u == 's':
                ms = v * 1000
            else:
                raise Exception(f'unknown unit {u}')
        total += ms
        count += 1
print('spans:', count, 'total ms:', total)
EOF
